let physicsVariants=[],physicsBank=[],physicsTopics=[];
const physicsDataReady=(async()=>{const raw=atob("");const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));const data=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text());physicsVariants=data.variants;physicsBank=data.bank;physicsTopics=data.topics;})();
